// Fork of "Adjustable Angle in Pixels" by Chimel. https://shadertoy.com/view/lXcBz2

// Using iq + Spalmer's Snap 45 method: https://www.shadertoy.com/view/M3ycWd

///////////////////////////////////////////////////////////
// Image Pass
// iChannel0 -> Buffer A
///////////////////////////////////////////////////////////

// -- 2D geometry helpers --------------------------------
float cross2D(vec2 a, vec2 b)
{
    return a.x*b.y - a.y*b.x;
}

// Check if point P is in triangle A-B-C
bool pointInTriangle(vec2 P, vec2 A, vec2 B, vec2 C)
{
    float areaABC = abs(cross2D(B - A, C - A));
    float areaPBC = abs(cross2D(B - P, C - P));
    float areaAPC = abs(cross2D(P - A, C - A));
    float areaABP = abs(cross2D(B - A, P - A));
    return (areaPBC + areaAPC + areaABP <= areaABC + 0.0001);
}

// Distance from P to an arm (pivot -> angle -> armLen)
float distanceToArm(vec2 P, vec2 pivot, float angle, float armLen)
{
    vec2 dir = vec2(cos(angle), sin(angle));
    float t  = dot(P - pivot, dir);
    if(t < 0.0 || t > armLen) return 99999.;
    return distance(P, pivot + t*dir);
}

// Distance from P to line-segment A->B
float distanceToSegment(vec2 P, vec2 A, vec2 B)
{
    vec2 AB = B - A;
    float t = dot(P - A, AB) / dot(AB, AB);
    t = clamp(t, 0.0, 1.0);
    return distance(P, A + t*AB);
}

// Circle-drawing helpers ---------------------------------
vec4 drawPivotCircle(vec2 fragCoord, vec2 pivot)
{
    float radius = 8.0;
    float border = 2.0;
    float d = distance(fragCoord, pivot);

    if(d < radius)
        return vec4(0.0, 0.0, 0.0, 1.0);  // black fill
    else if(d < radius + border)
        return vec4(1.000,1.000,1.000,1.0); // grey ring
    return vec4(-1.0);
}

// White fill circle w/ grey ring
vec4 drawWhiteCircle(vec2 fragCoord, vec2 cPos)
{
    float r = 8.0, b = 2.0;
    float d = distance(fragCoord, cPos);
    if(d < r)
        return vec4(1.0, 1.0, 1.0, 1.0);
    else if(d < r + b)
        return vec4(0.000,0.000,0.000,1.0);
    return vec4(-1.0);
}

// Red circle if arms acute, else white
vec4 drawMidGreenCircle(vec2 fragCoord, vec2 cPos, bool isAcute)
{
    float r = 8.0, b = 2.0;
    float d = distance(fragCoord, cPos);
    if(d < r)
    {
        if(isAcute) return vec4(1.000,0.000,0.435,1.0); // red if acute
        else        return vec4(1.0, 1.0, 1.0, 1.0); // white otherwise
    }
    else if(d < r + b)
    {
        return vec4(0.000,0.000,0.000,1.0);
    }
    return vec4(-1.0);
}

// --------------------------------------------------------
//   Old Geometric method: find smaller interior angle
// --------------------------------------------------------
/*
float getArmsSmallerAngle(float vertAngle)
{
    float raw = mod(vertAngle, 6.283185307);
    if(raw > 3.1415926535) // > π => reflex angle
        raw = 6.283185307 - raw;
    return raw;
}
*/

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //----------------------------------
    // 1) Read pivot + angles
    //----------------------------------
    vec4 stA = texelFetch(iChannel0, ivec2(0,0), 0);
    // pivot in [0..1]
    // verticalAngle, globalAngle in [0..1]
    vec2 pivotN   = stA.xy;
    float vertNor = stA.z;
    float globNor = stA.w;

    float vertAngle = vertNor * 6.283185307;  // 2π
    float globAngle = globNor * 6.283185307;  // 2π

    // Pixel-space pivot
    vec2 pivot = pivotN * iResolution.xy;

    // Angles for arms:
    float angleH = globAngle;             // "horizontal" arm
    float angleV = globAngle + vertAngle; // "vertical" arm

    //----------------------------------
    // 2) Basic background
    //----------------------------------
    vec3 color = vec3(0.95); // white background (or adjust as needed)

    // Arms in a "distance-based" manner:
    float armLen = 200.0;
    float thick  = 2.5;

    // Distances to each arm
    float dH = distanceToArm(fragCoord, pivot, angleH, armLen);
    float dV = distanceToArm(fragCoord, pivot, angleV, armLen);

    // If close to horizontal or vertical arm => set color
    if(dH < thick || dV < thick)
    {
        // Yellow arms
        color = vec3(1.000,0.800,0.000); 
    }

    // Grey line between midpoints of each arm
    vec2 tipH = pivot + armLen * vec2(cos(angleH), sin(angleH));
    vec2 tipV = pivot + armLen * vec2(cos(angleV), sin(angleV));
    vec2 midH = mix(pivot, tipH, 0.5);
    vec2 midV = mix(pivot, tipV, 0.5);

    float dG = distanceToSegment(fragCoord, midH, midV);
    if(dG < thick)
    {
        // let's pick a gray/teal
        color = vec3(0.729, 0.729, 0.729);
    }

    // Final base color
    fragColor = vec4(color, 1.0);

    //----------------------------------
    // 3) Overlay circles (pivot, tips, midpoints, midpoint-of-midpoints)
    //----------------------------------

    // ------------------------------------------------------------
    // Old Geometric method (commented out):
    // ------------------------------------------------------------
    //
    // float angleBetween = getArmsSmallerAngle(vertAngle);
    // bool armsAcute = (angleBetween < 1.57079632679); // π/2
    //
    // ------------------------------------------------------------

    // ------------------------------------------------------------
    // New iq+spalmer's way: check acuteness via dot product
    // ------------------------------------------------------------
    // If dot(dirH, dirV) > 0 => angle < 90°
    // dirH & dirV are unit vectors for each arm.
    vec2 dirH = vec2(cos(angleH), sin(angleH));
    vec2 dirV = vec2(cos(angleV), sin(angleV));
    bool armsAcute = (dot(dirH, dirV) > 0.0);

    // The midpoint of midH->midV
    vec2 midG = mix(midH, midV, 0.5);

    // Circle in the midpoint: red if acute, white if not
    vec4 c = drawMidGreenCircle(fragCoord, midG, armsAcute);
    if(c.x >= 0.0) fragColor = c;

    // Draw pivot circle on top
    c = drawPivotCircle(fragCoord, pivot);
    if(c.x >= 0.0) fragColor = c;

    // tipH
    c = drawWhiteCircle(fragCoord, tipH);
    if(c.x >= 0.0) fragColor = c;

    // tipV
    c = drawWhiteCircle(fragCoord, tipV);
    if(c.x >= 0.0) fragColor = c;

    // midH
    c = drawWhiteCircle(fragCoord, midH);
    if(c.x >= 0.0) fragColor = c;

    // midV
    c = drawWhiteCircle(fragCoord, midV);
    if(c.x >= 0.0) fragColor = c;
}

// Buffer A: Stores pivot, angles, etc.
//
// iChannel0 -> this Buffer A (ping-pong)
// iChannel3 -> Keyboard
///////////////////////////////////////////////////////////

// 1) Check if a key is pressed (GLSL function)
bool isKeyPressed(int kc)
{
    // Shadertoy Keyboard is iChannel3: a 256x1 texture.
    // Key 'kc' is pressed if .x > 0.5
    return texture(iChannel3, vec2((float(kc) + 0.5) / 256.0, 0.5)).x > 0.5;
}

// 2) Minimal pseudo-random generator
float rand(inout float seed)
{
    float r = fract(sin(seed * 1234.5678) * 43758.5453123);
    seed += 0.12345 + r * 0.98765;
    return r;
}

// We'll store an updated seed in a global so pixel(1,0) can write it out
float gUpdatedSeed = 0.0;

// 3) Move pivot with arrow keys
vec2 getKeyboardOffset()
{
    bool left  = isKeyPressed(37); // Left
    bool up    = isKeyPressed(38); // Up
    bool right = isKeyPressed(39); // Right
    bool down  = isKeyPressed(40); // Down

    float shift = 50.0 / min(iResolution.x, iResolution.y);
    vec2 offset = vec2(0.0);

    if (left)  offset.x -= shift;
    if (right) offset.x += shift;
    if (up)    offset.y += shift;
    if (down)  offset.y -= shift;

    return offset;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 cell = ivec2(fragCoord);

    // On the first frame, initialize pivot & angles
    if(iFrame == 0)
    {
        // (0,0): pivot = (0.5,0.5), verticalAngle=80° => ~0.2222, globalAngle=0
        if(all(equal(cell, ivec2(0,0))))
        {
            fragColor = vec4(0.5, 0.5, 80.0/360.0, 0.0);
        }
        // (1,0): oldR=0, seed=1234
        else if(all(equal(cell, ivec2(1,0))))
        {
            fragColor = vec4(0.0, 1234.0, 0.0, 0.0);
        }
        else
        {
            fragColor = vec4(0.0);
        }
        return;
    }

    // Otherwise, read old data
    vec4 oldA = texelFetch(iChannel0, ivec2(0,0), 0); // pivot, angles
    vec4 oldB = texelFetch(iChannel0, ivec2(1,0), 0); // oldR, seed

    // oldA: pivot=(x,y), verticalAngle=oldA.z, globalAngle=oldA.w
    vec2 pivotN   = oldA.xy; 
    float vertNor = oldA.z;
    float globNor = oldA.w;
    float vertAngle  = vertNor * 6.283185307; 
    float globalAng  = globNor * 6.283185307;

    // oldB: oldR=oldB.x, seed=oldB.y
    float oldR   = oldB.x;
    float seed   = oldB.y;

    // Default output = old data (pass-through)
    fragColor = texelFetch(iChannel0, cell, 0);

    // We'll only update pixel(0,0) and pixel(1,0) with new stuff
    if(all(equal(cell, ivec2(0,0))) || all(equal(cell, ivec2(1,0))))
    {
        float newVertNor = vertNor;
        float newGlobNor = globNor;
        float newR       = 0.0;
        float newSeed    = seed;

        // Check 'R' key toggle logic
        bool rNow   = isKeyPressed(82);  // 'R' keycode=82
        bool wasR   = (oldR > 0.5);
        bool rising = (rNow && !wasR);

        // Move pivot with arrow keys
        vec2 newPivotN = pivotN + getKeyboardOffset();
        newPivotN = clamp(newPivotN, vec2(0.0), vec2(1.0));

        // Mouse sets the vertical angle if pressed
        if(iMouse.z >= 0.0 && iMouse.x >= 0.0)
        {
            vec2 pivotS = newPivotN * iResolution.xy;
            vertAngle = atan(iMouse.y - pivotS.y, iMouse.x - pivotS.x);
        }

        // On R key press, toggle global angle between 0 and random
        if(rising)
        {
            if(abs(globalAng) < 0.0001)
            {
                float r = rand(newSeed);
                globalAng = r * 6.283185307; // random in [0..2π]
            }
            else
            {
                globalAng = 0.0;
            }
        }

        // Convert angles back to normalized [0..1]
        newVertNor = fract(vertAngle / 6.283185307);
        newGlobNor = fract(globalAng / 6.283185307);

        // Store if R is currently pressed
        newR = rNow ? 1.0 : 0.0;

        // Keep the updated seed
        gUpdatedSeed = newSeed;

        // Now write final updates into the correct pixel
        if(all(equal(cell, ivec2(0,0))))
        {
            // pivot & angles
            fragColor = vec4(newPivotN, newVertNor, newGlobNor);
        }
        else
        {
            // oldR, seed
            fragColor = vec4(newR, gUpdatedSeed, 0.0, 0.0);
        }
    }
}
